namespace Erlang;

internal sealed class DistributionDeferredExitReason : IDisposable
{
    private ReadOnlyMemory<byte> payload;
    private readonly Func<bool> forbiddenGateHeld;
    private readonly Func<ReadOnlyMemory<byte>, EtfDecodedTerm> decode;
    private readonly TaskCompletionSource<EtfDecodedTerm?> completed = new(TaskCreationOptions.RunContinuationsAsynchronously);
    private int claimed;

    internal DistributionDeferredExitReason(
        ReadOnlyMemory<byte> payload,
        Func<bool> forbiddenGateHeld,
        Func<ReadOnlyMemory<byte>, EtfDecodedTerm> decode
    )
    {
        // Own the raw bytes; do not parse even an empty/malformed dropped reason.
        this.payload = payload.ToArray();
        this.forbiddenGateHeld = forbiddenGateHeld;
        this.decode = decode;
    }

    internal Task<EtfDecodedTerm?> Prepare(
        Func<bool> shouldDecode,
        Action<Exception> malformedReason
    )
    {
        if (forbiddenGateHeld())
            throw new InvalidOperationException(DistributionDeferredExitReasonDiagnostics.Locked);
        if (Volatile.Read(ref claimed) != 0)
            return completed.Task;
        if (Interlocked.CompareExchange(ref claimed, 1, 0) != 0)
            return completed.Task;
        bool eligible;
        try
        {
            // Caller commits native target/link drop/removal before reason decode.
            // No private lock is held while running either supplied callback.
            eligible = shouldDecode();
        }
        catch (Exception exception)
        {
            Finish(null, exception);

            return completed.Task;
        }
        if (!eligible)
        {
            Finish(null, null);

            return completed.Task;
        }
        try
        {
            if (forbiddenGateHeld())
                throw new InvalidOperationException(DistributionDeferredExitReasonDiagnostics.Locked);
            EtfDecodedTerm result = decode(payload);
            Finish(result, null);
        }
        catch (Exception exception)
        {
            if (IsMalformed(exception))
            {
                try
                {
                    // Caller closes only its captured connection generation.
                    malformedReason(exception);
                }
                catch (Exception closeFailure)
                {
                    Finish(null, new AggregateException(exception, closeFailure));

                    return completed.Task;
                }
            }
            Finish(null, exception);
        }

        return completed.Task;
    }

    public void Dispose()
    {
        if (Interlocked.CompareExchange(ref claimed, 1, 0) != 0)
            return;
        Finish(null, null);
    }

    private void Finish(EtfDecodedTerm? result, Exception? exception)
    {
        payload = ReadOnlyMemory<byte>.Empty;
        if (exception is null)
            completed.TrySetResult(result);
        else
            completed.TrySetException(exception);
    }

    internal static bool IsMalformed(Exception exception)
        => exception is ArgumentException or EndOfStreamException or InvalidDataException or FormatException or OverflowException ||
            exception is ErlangException { Reason: Atom { Name: ErlangErrorReasons.BadArgument or ErlangErrorReasons.SystemLimit } };
}

namespace Erlang;

internal static class DistributionDeferredExitReasonDiagnostics
{
    internal const string Locked = "Deferred exit reason factories must execute outside runtime and mailbox gates.";
    internal const string Payload = "Deferred distribution reason is not an allowed versioned ETF payload.";
}

namespace Erlang;

internal sealed class DistributionSignalDrain
{
    private static readonly AsyncLocal<DistributionSignalDrainFlow?> current = new();
    private readonly object gate = new();
    private TaskCompletionSource? completed;

    internal bool IsCurrent => current.Value is { Active: true } flow && ReferenceEquals(flow.Owner, this);

    internal void RequireSafeNestedWait()
    {
        if (current.Value is not { Active: true } || IsCurrent)
            return;
        lock (gate)
        {
            if (completed is not null)
                throw new DistributionSignalNestedWaitException();
        }
    }

    internal void Run(Action drain)
    {
        if (IsCurrent)
            return;
        while (true)
        {
            Task? preceding;
            lock (gate)
            {
                preceding = completed?.Task;
                if (preceding is null)
                    completed = new(TaskCreationOptions.RunContinuationsAsynchronously);
            }
            if (preceding is null)
                break;
            if (current.Value is { Active: true })
                throw new DistributionSignalNestedWaitException();
            preceding.GetAwaiter().GetResult();
        }
        DistributionSignalDrainFlow? parent = current.Value;
        var flow = new DistributionSignalDrainFlow(this);
        current.Value = flow;
        try
        {
            drain();
        }
        finally
        {
            flow.Active = false;
            current.Value = parent;
            TaskCompletionSource finished;
            lock (gate)
            {
                finished = completed!;
                completed = null;
            }
            finished.TrySetResult();
        }
    }
}

namespace Erlang;

internal static class DistributionSignalDrainDiagnostics
{
    internal const string NestedWait = "A HOST distribution constructor cannot wait for another active deferred owner drain.";
}

namespace Erlang;

internal sealed class DistributionSignalDrainFlow(DistributionSignalDrain owner)
{
    internal DistributionSignalDrain Owner { get; } = owner;
    internal volatile bool Active = true;
}

namespace Erlang;

internal sealed class DistributionSignalNestedWaitException : InvalidOperationException
{
    internal DistributionSignalNestedWaitException()
        : base(DistributionSignalDrainDiagnostics.NestedWait)
    {
    }
}

