namespace Erlang;

public sealed partial class ProcessRuntime
{
    internal DistributionDeferredExitReason CreateDeferredDistributionExitReason(
        ReadOnlyMemory<byte> payload,
        Func<bool>? additionalGateHeld = null
    )
        => new(
            payload,
            () => System.Threading.Monitor.IsEntered(gate) || additionalGateHeld?.Invoke() == true,
            DecodeDeferredDistributionExitReason
        );

    private EtfDecodedTerm DecodeDeferredDistributionExitReason(ReadOnlyMemory<byte> payload)
    {
        // AdmitExternalDecode captures the actual decode-time local epoch.
        // Its function factories and final graph validation remain outside gate.
        if (System.Threading.Monitor.IsEntered(gate))
            throw new InvalidOperationException(DistributionDeferredExitReasonDiagnostics.Locked);
        if (payload.Length < EtfHeaderLayout.MinimumPacketBytes ||
            payload.Span[EtfHeaderLayout.TagOffset] is EtfTags.Compressed or EtfTags.Local)
            throw new ArgumentException(DistributionDeferredExitReasonDiagnostics.Payload, nameof(payload));

        return ImportExternalTerm(payload.Span);
    }
}

namespace Erlang;

public sealed partial class ProcessRuntime
{
    internal void QueueDeferredProcessSignal(
        ProcessContext owner,
        Func<DeferredMailboxAdmission?> prepare,
        Action release,
        Term? from = null,
        Term? traceToken = null
    )
    {
        lock (gate)
        {
            if (!ReferenceEquals(owner.Runtime, this) || !processes.TryGetValue(owner.Self, out var found) ||
                !ReferenceEquals(found, owner) || owner.Terminated)
            {
                release();

                return;
            }
            owner.DeferredSignalDrain ??= new();
            owner.Mailbox.SendDeferred(
                prepare,
                release,
                from,
                traceToken
            );
        }
    }

    private void DrainDeferredProcessSignals(ProcessContext owner)
    {
        while (true)
        {
            MailboxDeferredPreparation? work;
            lock (gate)
            {
                if (owner.Terminated)
                {
                    owner.Mailbox.DiscardPending();

                    return;
                }
                owner.Mailbox.AdmitPending();
                if (owner.Terminated)
                {
                    owner.Mailbox.DiscardPending();

                    return;
                }
                work = owner.Mailbox.ClaimDeferred();
            }
            if (work is null)
                return;
            DeferredMailboxAdmission? ready;
            try
            {
                // Neither global runtime nor mailbox gate is held here.
                ready = work.Prepare();
            }
            catch
            {
                lock (gate)
                    work.Complete(null);
                throw;
            }
            lock (gate)
                work.Complete(owner.Terminated ? null : ready);
        }
    }
}

namespace Erlang;

public sealed partial class ProcessRuntime
{
    internal void QueueConnectedDeferredExit(
        RuntimeDistributionPendingEntry entry,
        DistributionConnectedEntry connected,
        Pid remote,
        Pid local,
        ReadOnlyMemory<byte> payload,
        Term traceToken,
        bool explicitSignal,
        Action<Exception> malformedReason
    )
    {
        ProcessContext target;
        DistributionProcessLink? link;
        lock (gate)
        {
            if (!IsCurrentLocal(local) || !processes.TryGetValue(local, out target!))
                return;
            link = explicitSignal ? null : distributionProcessLinks.LastOrDefault(item =>
                ReferenceEquals(item.Entry, entry) && ReferenceEquals(item.Connection, connected) &&
                item.ConnectionId == entry.ConnectionId && ReferenceEquals(item.Local, target) && item.Remote.Equals(remote));
            if (!explicitSignal && link is null)
                return;
        }
        var reason = CreateDeferredDistributionExitReason(payload, () => target.Mailbox.DeferredGateHeld);
        bool priority = false;

        bool Eligible()
        {
            lock (gate)
            {
                if (!IsOwnedLiveNodeProcess(target))
                    return false;
                if (link is null)
                    return true;
                distributionProcessLinks.Remove(link);
                if (!target.LinkIdentities.TryGetValue(remote, out var current) || !ReferenceEquals(current, link.Identity) ||
                    current.PendingUnlink is not null || !target.Links.Contains(remote))
                    return false;
                priority = target.PriorityLinks.Contains(remote);
                RemoveDistributionLinkIdentity(link);

                return true;
            }
        }

        DeferredMailboxAdmission? Prepare()
        {
            EtfDecodedTerm? decoded;
            try
            {
                decoded = reason.Prepare(Eligible, malformedReason).GetAwaiter().GetResult();
            }
            catch (Exception exception) when (DistributionDeferredExitReason.IsMalformed(exception))
            {
                return null;
            }
            if (decoded is null)
                return null;
            Term value = decoded.Term;
            lock (gate)
            {
                if (!IsOwnedLiveNodeProcess(target))
                    return null;
                bool kill = explicitSignal && value.Equals(Term.A(ProcessExitSignals.Kill));
                if (target.TrapExits && !kill)
                    return new(Term.Tuple(Term.A(ProcessMessageTags.LinkedExit), remote, value), priority);
                if (!kill && value.Equals(Term.A(ProcessExitReasons.Normal)))
                    return null;
                Terminate(target, kill ? Term.A(ProcessExitReasons.Killed) : value);

                return null;
            }
        }
        QueueDeferredProcessSignal(
            target,
            Prepare,
            reason.Dispose,
            remote,
            traceToken
        );
    }
}

namespace Erlang;

public sealed partial class ProcessRuntime
{
    internal async ValueTask<Term> QueryProcessInfo(
        ProcessContext requester,
        Pid target,
        IReadOnlyList<ProcessInfoItem> keys,
        bool singleton
    )
    {
        requester.Cancellation.ThrowIfCancellationRequested();
        if (target.Equals(requester.Self) || !keys.Any(key => key.RequiresOwnerSnapshot))
            return ProcessInfo(target, keys, singleton);
        var request = new ProcessInfoRequest(
            requester,
            MakeReference(),
            keys,
            singleton
        );
        lock (gate)
        {
            if (!processes.TryGetValue(target, out var process))
                return ProcessInfoAtoms.Undefined;
            process.DeferredSignalDrain?.RequireSafeNestedWait();
            process.PendingInfoRequests.Add(request);
            process.Mailbox.SendPending(
                Nil.Value,
                () =>
            {
                lock (gate)
                {
                    if (process.PendingInfoRequests.Remove(request))
                        ReplyProcessInfo(request, ProcessInfo(target, request.Keys, request.Singleton), process.Self);
                }

                return null;
            }
            );
        }
        var reply = await requester.ReceiveAsync(message => message is TupleTerm { Items.Count: 2 } tuple && tuple.Items[0].Equals(request.Id) ? tuple : null);

        return reply!.Items[1];
    }

    private void ReplyProcessInfo(ProcessInfoRequest request, Term result, Term? from = null) => SendSystem(request.Requester.Self, Term.Tuple(request.Id, result), from);

    private Term SnapshotOriginMonitors(Pid observer) => Cons.From(monitors.Values.Where(monitor => monitor.Observer.Equals(observer)).Select(monitor => Term.Tuple(
        Term.A(monitor.Source switch
        {
            ProcessMonitorSource.Port => ProcessMonitorKinds.Port,
            ProcessMonitorSource.TimeOffset => ProcessMonitorKinds.TimeOffset,
            _ => ProcessMonitorKinds.Process
        }),
        monitor.ReportedTarget
    )));
}

